export SIM_VER_XSIM=2025.2
export GCC_VER_XSIM=9.3.0

# catch pipeline exit status
set -Eeuo pipefail

# resolve compiled library path in xsim.ini
export RDI_DATADIR="/run/media/luis/WNFN/fpga2/${SIM_VER_XSIM}.1/data"
# compile Verilog/System Verilog design sources
echo "xvlog --incr --relax -L uvm -prj phase11_top_vlog.prj"
xvlog --incr --relax -L uvm -prj phase11_top_vlog.prj 2>&1 | tee compile.log

# compile VHDL design sources
echo "xvhdl --incr --relax -prj phase11_top_vhdl.prj"
xvhdl --incr --relax -prj phase11_top_vhdl.prj 2>&1 | tee -a compile.log

echo "Waiting for jobs to finish..."
echo "No pending jobs, compilation finished."
